    return found


# ---- Load data ----
with open(f'{ROOT}/campaign_manifest.json') as f:
    manifest = json.load(f)

crate_cost_rows = load_csv(f'{ROOT}/crate_cost.csv')
billing_rows = load_csv(f'{ROOT}/billing.csv')
override_rows = load_csv(f'{ROOT}/location_overrides.csv')
suspension_rows = load_csv(f'{ROOT}/suspensions.csv')

# ---- Build lookup structures ----
crate_cost_map = {}
for row in crate_cost_rows:
    crate_cost_map[row['crate_tier'].strip()] = d(row['crate_cost_usd'])

suspended_ids = set()
for row in suspension_rows:
    if row['suspension_status'].strip().lower() == 'hold':
        suspended_ids.add(row['campaign_id'].strip())

# ---- Filter campaigns: analysis_flag == 'review' and not suspended ----
retained = []
for campaign in flatten_campaigns(manifest):
    if str(campaign.get('analysis_flag', '')).strip().lower() != 'review':
        continue
    campaign_id = str(campaign['campaign_id']).strip()
    if campaign_id in suspended_ids:
        continue
    retained.append(campaign)

# ---- Resolve billing rows ----
name_to_campaign = {}
for campaign in retained:
    campaign_id = str(campaign['campaign_id']).strip()
    campaign_name = str(campaign['campaign_name']).strip()
    name_to_campaign[campaign_name] = campaign_id
    aliases = campaign.get('alias_labels', [])
    if isinstance(aliases, str):
        aliases = [alias.strip() for alias in aliases.split(',')]
    for alias in aliases:
        alias = str(alias).strip()
        if alias:
            name_to_campaign[alias] = campaign_id

billing_by_campaign = {}
for row in billing_rows:
    if row['status'].strip().lower() != 'active':
        continue
    label = row['campaign_label'].strip()
    campaign_id = name_to_campaign.get(label)
    if campaign_id is None:
        continue
    billing_by_campaign.setdefault(campaign_id, []).append(row)


def cycle_sort_key(row):
    cycle_tag = row['cycle_tag'].strip()
    try:
        return (0, d(cycle_tag))
    except Exception:
        return (1, cycle_tag)


billing_selected = {}
for campaign_id, rows in billing_by_campaign.items():
    billing_selected[campaign_id] = sorted(rows, key=cycle_sort_key)[-1]

# ---- Resolve active clinics from location_overrides ----
override_by_campaign = {}
for row in override_rows:
    if row['state'].strip().lower() != 'approved':
        continue
    revision = row.get('revision', '').strip()
    active_clinics = row.get('active_clinics', '').strip()
    if not revision or not active_clinics:
        continue
    campaign_id = row['campaign_id'].strip()
    override_by_campaign.setdefault(campaign_id, []).append(row)

clinic_override = {}
for campaign_id, rows in override_by_campaign.items():
    best = max(rows, key=lambda row: d(row['revision']))
    clinic_override[campaign_id] = int(d(best['active_clinics']))

# ---- Build per-campaign results ----
results = []
for campaign in retained:
    campaign_id = str(campaign['campaign_id']).strip()
    campaign_name = str(campaign['campaign_name']).strip()

    if campaign_id in clinic_override:
        active_clinics = clinic_override[campaign_id]
    else:
        active_clinics = int(d(campaign['default_active_clinics']))

    drug_cost_per_1000 = d(campaign['drug_cost_per_1000_doses_usd'])
    doses_per_day = d(campaign['doses_per_day'])
    crate_tier = str(campaign['crate_tier']).strip()
    crate_cost = crate_cost_map[crate_tier]

    if campaign_id not in billing_selected:
        continue
    payment = d(billing_selected[campaign_id]['payment_per_dispatch_per_clinic_usd'])

    days6 = Decimal('6')
    disp6 = Decimal('60')
    rev6 = payment * active_clinics * disp6
    drug6 = drug_cost_per_1000 * active_clinics * doses_per_day * days6 * disp6 / Decimal('1000')
    crate6 = crate_cost * active_clinics * disp6
    margin6 = rev6 - drug6 - crate6

    days12 = Decimal('12')
    disp12 = Decimal('30')
    rev12 = payment * active_clinics * disp12
    drug12 = drug_cost_per_1000 * active_clinics * doses_per_day * days12 * disp12 / Decimal('1000')
    crate12 = crate_cost * active_clinics * disp12
    margin12 = rev12 - drug12 - crate12

    diff = margin12 - margin6

    results.append({
        'campaign_id': campaign_id,
        'campaign_name': campaign_name,
        'active_clinics': active_clinics,
        'drug_cost_per_1000_doses_usd': money(drug_cost_per_1000),
        'doses_per_day': money(doses_per_day),
        'crate_tier': crate_tier,
        'crate_cost_usd': money(crate_cost),
        'payment_per_dispatch_per_clinic_usd': money(payment),
        'annual_drug_cost_6_day_usd': money(drug6),
        'annual_drug_cost_12_day_usd': money(drug12),
        'annual_crate_cost_6_day_usd': money(crate6),
        'annual_crate_cost_12_day_usd': money(crate12),
        'annual_revenue_6_day_usd': money(rev6),
        'annual_revenue_12_day_usd': money(rev12),
        'annual_margin_6_day_usd': money(margin6),
        'annual_margin_12_day_usd': money(margin12),
        'annual_margin_difference_12_minus_6_usd': money(diff),
    })

results.sort(key=lambda row: row['campaign_id'])

# ---- Totals ----
total_margin_6 = money(sum(d(row['annual_margin_6_day_usd']) for row in results))
total_margin_12 = money(sum(d(row['annual_margin_12_day_usd']) for row in results))
total_diff = money(sum(d(row['annual_margin_difference_12_minus_6_usd']) for row in results))
abs_diff = money(abs(d(total_diff)))

if d(abs_diff) < Decimal('11000'):
    decision = 'move_to_12_day'
    justification = f'Absolute total margin difference ${abs_diff:,.2f} is below the $11,000 threshold, so consolidating to 12-day dispatches is recommended.'
else:
    decision = 'keep_6_day'
    justification = f'Absolute total margin difference ${abs_diff:,.2f} meets or exceeds the $11,000 threshold, so keeping 6-day dispatches is recommended.'

output = {
    'assumptions': {
        'dispatches_per_year_6_day': 60,
        'dispatches_per_year_12_day': 30,
        'days_per_dispatch_6_day': 6,
        'days_per_dispatch_12_day': 12,
        'switch_threshold_usd': 11000,
        'override_rule': 'highest numeric approved revision with non-empty active_clinics, else default_active_clinics',
        'suspension_rule': 'exclude hold campaigns',
    },
    'campaigns': results,
    'totals': {
        'total_annual_margin_6_day_usd': total_margin_6,
        'total_annual_margin_12_day_usd': total_margin_12,
        'total_annual_margin_difference_12_minus_6_usd': total_diff,
        'absolute_total_margin_difference_usd': abs_diff,
    },
    'recommendation': {
        'decision': decision,
        'justification': justification,
    },
}

with open(f'{ROOT}/vaxcrate_analysis.json', 'w') as f:
    json.dump(output, f, indent=2)

print('JSON written.')
print(f'Campaigns retained: {len(results)}')
for row in results:
    print(
        f"  {row['campaign_id']}: clinics={row['active_clinics']}, "
        f"margin6={row['annual_margin_6_day_usd']}, "
        f"margin12={row['annual_margin_12_day_usd']}, "
        f"diff={row['annual_margin_difference_12_minus_6_usd']}"
    )
print(f'Total margin 6-day: {total_margin_6}')
print(f'Total margin 12-day: {total_margin_12}')
print(f'Total diff: {total_diff}')
print(f'Abs diff: {abs_diff}')
print(f'Decision: {decision}')

summary_lines = [
    '# VaxCrate 6-Day vs 12-Day Dispatch Analysis Summary',
    '',
    f'Total 6-day annual margin: ${total_margin_6:,.2f} USD',
    f'Total 12-day annual margin: ${total_margin_12:,.2f} USD',
    f'Absolute margin difference: ${abs_diff:,.2f} USD',
    f'Recommendation: {decision}',
]

with open(f'{ROOT}/vaxcrate_summary.md', 'w') as f:
    f.write('\n'.join(summary_lines) + '\n')

print('Summary written.')

